      "index.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Digital Calculator | FAHMRISE</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <div class=\"calculator\">\n    <div class=\"display\">\n      <div id=\"prevScreen\" class=\"prev-op\"></div>\n      <div id=\"screen\" class=\"current-val\">0</div>\n    </div>\n    <div class=\"keypad\">\n      <button class=\"key action\" id=\"clearBtn\">AC</button>\n      <button class=\"key action\" id=\"deleteBtn\">DEL</button>\n      <button class=\"key op\" data-op=\"/\">÷</button>\n      <button class=\"key op\" data-op=\"*\">×</button>\n\n      <button class=\"key num\" data-num=\"7\">7</button>\n      <button class=\"key num\" data-num=\"8\">8</button>\n      <button class=\"key num\" data-num=\"9\">9</button>\n      <button class=\"key op\" data-op=\"-\">-</button>\n\n      <button class=\"key num\" data-num=\"4\">4</button>\n      <button class=\"key num\" data-num=\"5\">5</button>\n      <button class=\"key num\" data-num=\"6\">6</button>\n      <button class=\"key op\" data-op=\"+\">+</button>\n\n      <button class=\"key num\" data-num=\"1\">1</button>\n      <button class=\"key num\" data-num=\"2\">2</button>\n      <button class=\"key num\" data-num=\"3\">3</button>\n      <button class=\"key equals\" id=\"equalsBtn\">=</button>\n\n      <button class=\"key num zero\" data-num=\"0\">0</button>\n      <button class=\"key num\" data-num=\".\">.</button>\n    </div>\n  </div>\n  <script src=\"script.js\"></script>\n</body>\n</html>",
      "style.css": "body {\n  font-family: 'Courier New', monospace;\n  background-color: #020617;\n  color: #fff;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 90vh;\n  margin: 0;\n  padding: 20px;\n}\n\n.calculator {\n  width: 100%;\n  max-width: 320px;\n  background: #0f172a;\n  padding: 20px;\n  border-radius: 20px;\n  border: 1px solid #334155;\n  box-shadow: 0 15px 35px rgba(0,0,0,0.5);\n}\n\n.display {\n  background: #020617;\n  border-radius: 12px;\n  padding: 16px;\n  text-align: right;\n  margin-bottom: 20px;\n  border: 1px solid #1e293b;\n  min-height: 60px;\n  display: flex;\n  flex-direction: column;\n  justify-content: flex-end;\n}\n\n.prev-op {\n  font-size: 13px;\n  color: #64748b;\n  min-height: 18px;\n}\n\n.current-val {\n  font-size: 28px;\n  font-weight: bold;\n  color: #10b981;\n  word-break: break-all;\n}\n\n.keypad {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 10px;\n}\n\n.key {\n  padding: 16px 0;\n  font-size: 18px;\n  font-weight: bold;\n  border: none;\n  border-radius: 10px;\n  background: #1e293b;\n  color: #fff;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.key:hover {\n  filter: brightness(1.2);\n}\n\n.key:active {\n  transform: scale(0.96);\n}\n\n.key.op {\n  background: #2563eb;\n  color: #fff;\n}\n\n.key.action {\n  background: #ef4444;\n  color: #fff;\n}\n\n.key.equals {\n  background: #10b981;\n  color: #020617;\n  grid-row: span 2;\n  height: 100%;\n}\n\n.key.zero {\n  grid-column: span 2;\n}",
      "script.js": "// DOM Elements\nconst screen = document.getElementById('screen');\nconst prevScreen = document.getElementById('prevScreen');\nconst numKeys = document.querySelectorAll('.key.num');\nconst opKeys = document.querySelectorAll('.key.op');\nconst clearBtn = document.getElementById('clearBtn');\nconst deleteBtn = document.getElementById('deleteBtn');\nconst equalsBtn = document.getElementById('equalsBtn');\n\nlet current = '0';\nlet previous = '';\nlet operation = null;\n\nfunction updateDisplay() {\n  screen.textContent = current;\n  if (operation != null) {\n    prevScreen.textContent = `${previous} ${operation}`;\n  } else {\n    prevScreen.textContent = '';\n  }\n}\n\nfunction appendNumber(number) {\n  if (number === '.' && current.includes('.')) return;\n  if (current === '0' && number !== '.') {\n    current = number.toString();\n  } else {\n    current = current.toString() + number.toString();\n  }\n  updateDisplay();\n}\n\nfunction chooseOperation(op) {\n  if (current === '') return;\n  if (previous !== '') {\n    compute();\n  }\n  operation = op;\n  previous = current;\n  current = '';\n  updateDisplay();\n}\n\nfunction compute() {\n  let computation;\n  const prev = parseFloat(previous);\n  const curr = parseFloat(current);\n  if (isNaN(prev) || isNaN(curr)) return;\n\n  switch (operation) {\n    case '+': computation = prev + curr; break;\n    case '-': computation = prev - curr; break;\n    case '*': computation = prev * curr; break;\n    case '/': computation = curr === 0 ? 'Error' : prev / curr; break;\n    default: return;\n  }\n\n  current = computation.toString();\n  operation = null;\n  previous = '';\n  updateDisplay();\n}\n\nfunction clearAll() {\n  current = '0';\n  previous = '';\n  operation = null;\n  updateDisplay();\n}\n\nfunction deleteDigit() {\n  current = current.toString().slice(0, -1);\n  if (current === '') current = '0';\n  updateDisplay();\n}\n\nnumKeys.forEach(btn => btn.addEventListener('click', () => appendNumber(btn.dataset.num)));\nopKeys.forEach(btn => btn.addEventListener('click', () => chooseOperation(btn.dataset.op)));\nequalsBtn.addEventListener('click', compute);\nclearBtn.addEventListener('click', clearAll);\ndeleteBtn.addEventListener('click', deleteDigit);\n\nconsole.log('Calculator ready!');"
